'use strict';
// Only the curated, readable JSON is edited. Browser data is generated from it.
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../public/data');
const bank=JSON.parse(fs.readFileSync(path.join(root,'contrasts.json'),'utf8'));
fs.writeFileSync(path.join(root,'contrasts.js'),
  '/* Generated from contrasts.json. Do not edit this file directly. */\nwindow.ORDJAKTEN_CONTRASTS = '+JSON.stringify(bank)+';\n');
console.log(`✓ Synced ${bank.pairs.length} concept pairs.`);
